for(const title of ['Cigar journal','Journal','Checklist'])test(`full template ${title} preserves prose and persists on mobile`,async({page})=>{
 await page.setViewportSize({width:390,height:844});await login(page);await create(page,'Writing/Full template.md','Existing prose');const source=page.getByLabel('Markdown source');await source.press('Control+End');await page.getByRole('button',{name:'Templates',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Templates',exact:true});await expect(dialog.getByRole('tab',{name:'Section templates',exact:true})).toBeVisible();await dialog.getByRole('tab',{name:'Full templates',exact:true}).click();await expect(source).toHaveValue('Existing prose');await dialog.getByRole('button',{name:`Insert ${title.toLowerCase()} template`,exact:true}).click();await expect(dialog).toHaveCount(0);await expect(source).toHaveValue(new RegExp('Existing prose[\\s\\S]*# '+title));if(title==='Checklist')await expect(source).toHaveValue(/- \[ \] First task/);await page.getByRole('button',{name:'Save file',exact:true}).click();await expect(page.locator('.network')).toHaveText('Synchronized');const value=await source.inputValue();await page.reload();await expect(page.getByRole('button',{name:'Settings',exact:true})).toBeVisible();if(!await page.locator('.sidebar').isVisible())await page.getByRole('button',{name:'Toggle folders',exact:true}).click();await selectDropdown(page.getByLabel('Select a file in the map'),{label:'Full template'});await page.getByRole('button',{name:'Open file',exact:true}).click();await page.getByRole('button',{name:'Source',exact:true}).click();await expect(source).toHaveValue(value);
});
