test('files drag between folders with animated pickup and drop feedback',async({page})=>{await login(page);await create(page,'Writing/Move me.md','# Moving');if(!await page.locator('.sidebar').isVisible())await page.getByRole('button',{name:'Toggle folders'}).click();await page.getByRole('button',{name:'Create',exact:true}).click();await page.getByRole('menuitem',{name:'New folder'}).click();await page.getByLabel('New folder path').fill('Archive');await page.getByRole('button',{name:'Create folder',exact:true}).click();if(!await page.locator('.sidebar').isVisible())await page.getByRole('button',{name:'Toggle folders'}).click();await page.locator('[data-folder="Writing"] > summary').click();const source=page.locator('nav').getByRole('button',{name:'Move me',exact:true});const target=page.locator('[data-folder="Archive"] summary');await expect(target).toBeVisible();await source.hover();const a=(await source.boundingBox())!,b=(await target.boundingBox())!;await page.mouse.move(a.x+a.width/2,a.y+a.height/2);await page.mouse.down();await page.mouse.move(a.x+a.width/2+12,a.y+a.height/2,{steps:3});await expect(page.locator('.drag-ghost')).toBeVisible();await expect(source).toHaveClass(/drag-source/);await page.mouse.move(b.x+b.width/2,b.y+b.height/2,{steps:8});await expect(page.locator('[data-folder="Archive"]')).toHaveClass(/drop-target/);await expect(target).toHaveCSS('transform',/matrix/);await page.mouse.up();await expect(page.locator('.drag-ghost')).toHaveCount(0);await expect(page.getByLabel('File path')).toHaveValue('Archive/Move me.md');});
test('folders drag safely into other folders and preserve the selected file path',async({page})=>{await login(page);await create(page,'Folder to move/Inside.md','# Inside');if(!await page.locator('.sidebar').isVisible())await page.getByRole('button',{name:'Toggle folders'}).click();await page.getByRole('button',{name:'Create',exact:true}).click();await page.getByRole('menuitem',{name:'New folder'}).click();await page.getByLabel('New folder path').fill('Folder destination');await page.getByRole('button',{name:'Create folder',exact:true}).click();if(!await page.locator('.sidebar').isVisible())await page.getByRole('button',{name:'Toggle folders'}).click();const source=page.locator('[data-folder="Folder to move"] > summary'),target=page.locator('[data-folder="Folder destination"] > summary');await source.hover();const a=(await source.boundingBox())!,b=(await target.boundingBox())!;await page.mouse.move(a.x+24,a.y+a.height/2);await page.mouse.down();await page.mouse.move(a.x+40,a.y+a.height/2,{steps:3});await expect(page.locator('.drag-ghost')).toBeVisible();await page.mouse.move(b.x+b.width/2,b.y+b.height/2,{steps:8});await expect(page.locator('[data-folder="Folder destination"]')).toHaveClass(/drop-target/);await page.mouse.up();await expect(page.getByLabel('File path')).toHaveValue('Folder destination/Folder to move/Inside.md');});
