 const dialog=page.getByRole('dialog',{name:'Create Markdown table'});
 await expect(dialog.getByRole('toolbar',{name:'Editor formatting'})).toBeVisible();
 const cell=dialog.getByLabel('Row 1, column 1',{exact:true});await expect(cell).toHaveAttribute('contenteditable','true');await cell.fill('hello');
 await selectCellText(cell);
 await dialog.getByRole('button',{name:'Bold',exact:true}).click();await expect(cell).toHaveText('hello');await expect(cell.locator('strong')).toHaveText('hello');
 await dialog.getByRole('button',{name:'Heading',exact:true}).click();await expect(dialog.getByRole('button',{name:'Heading 2',exact:true})).toBeVisible();
 await dialog.getByRole('button',{name:'Heading 2',exact:true}).click();await expect(cell).toHaveText('hello');await expect(cell.locator('h2 strong')).toHaveText('hello');
 const other=dialog.getByLabel('Row 1, column 2',{exact:true});await other.fill('second');
 await selectCellText(other);await dialog.getByRole('button',{name:'Italic',exact:true}).click();await expect(other).toHaveText('second');await expect(other.locator('em')).toHaveText('second');
 await expect(cell).toHaveText('hello');await expect(cell.locator('h2 strong')).toHaveText('hello');
 await dialog.getByRole('button',{name:'List',exact:true}).click();await expect(dialog.getByRole('button',{name:'Lowercase letters',exact:true})).toBeVisible();await dialog.getByRole('button',{name:'Lowercase letters',exact:true}).click();await expect(other).toHaveText('second');await expect(other.locator('ol')).toHaveCSS('list-style-type','lower-alpha');
 await dialog.getByRole('button',{name:'Alignment',exact:true}).click();await dialog.getByRole('button',{name:'Align center',exact:true}).click();await expect(other).toHaveText('second');await expect(other.locator('ol')).toHaveCSS('list-style-type','lower-alpha');
 await dialog.getByRole('button',{name:'Cancel',exact:true}).click();await expect(page.getByLabel('Markdown source')).toHaveValue('Keep this note');
 await page.getByRole('button',{name:'Table',exact:true}).click();const fresh=page.getByRole('dialog',{name:'Create Markdown table'});await fresh.getByLabel('Header 1',{exact:true}).fill('Title');await selectCellText(fresh.getByLabel('Header 1',{exact:true}));await fresh.getByRole('button',{name:'Bold',exact:true}).click();await fresh.getByRole('button',{name:'Insert table',exact:true}).click();await expect(page.getByLabel('Markdown source')).toHaveValue(/\*\*Title\*\*/);
