test('long pressing a folder can move its notes to automatic Unsorted',async({browser})=>{
 const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});const page=await context.newPage();await login(page);
 await create(page,'Delete me/Reassigned note.md','# keep');await synced(page);
 if(!await page.locator('.sidebar').isVisible())await page.getByRole('button',{name:'Toggle folders'}).click();
 const folder=page.locator('summary',{hasText:'Delete me'});await folder.dispatchEvent('pointerdown',{pointerType:'touch',button:0});await page.waitForTimeout(650);await folder.dispatchEvent('pointerup',{pointerType:'touch',button:0});
 await expect(page.getByRole('dialog',{name:'Delete folder'})).toBeVisible();
 await page.getByRole('button',{name:'Keep files'}).click();
 await expect(page.getByRole('dialog',{name:'Reassign folder files'})).toContainText('Do you want to move these files to another folder?');
 await page.getByRole('button',{name:'No, keep folder'}).click();
 await expect(page.getByRole('dialog')).toHaveCount(0);await expect(page.locator('nav')).toContainText('Delete me');
 await folder.dispatchEvent('pointerdown',{pointerType:'touch',button:0});await page.waitForTimeout(650);await folder.dispatchEvent('pointerup',{pointerType:'touch',button:0});
 await page.getByRole('button',{name:'Keep files'}).click();
 await page.getByRole('button',{name:'Reassign files'}).click();
 await expect(page.getByLabel('Destination folder')).toBeVisible();
 await selectDropdown(page.getByLabel('Destination folder'),'__unsorted__');
 await page.getByRole('button',{name:'Move files and delete folder'}).click();
 await expect(page.locator('nav')).not.toContainText('Delete me');await expect(page.locator('nav')).toContainText('Unsorted');
 await openNote(page,'Reassigned note');await expect(page.getByLabel('File path')).toHaveValue('Unsorted/Reassigned note.md');await context.close();
});

test('date insertion cannot move the caret after the next edit has started',async({page})=>{
 await login(page);await create(page,'Writing/Temporal caret.md','Before replace after');const source=page.getByLabel('Markdown source');
 // Hold selection-restoration frames to exercise the delayed-frame race deterministically.
 await page.evaluate(()=>{const native=window.requestAnimationFrame.bind(window);(window as any).__caretFrames=[];window.requestAnimationFrame=(callback:FrameRequestCallback)=>callback.toString().includes('setSelectionRange')?((window as any).__caretFrames.push(callback),-1):native(callback);});
 await source.evaluate((el:HTMLTextAreaElement)=>el.setSelectionRange(7,14));await page.getByRole('button',{name:'Date & time',exact:true}).click();await page.getByRole('button',{name:'YYYY-MM-DD',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Insert date',exact:true});await dialog.getByRole('button',{name:'Manual',exact:true}).click();await dialog.getByLabel('Date',{exact:true}).fill('2030-12-25');await dialog.getByRole('button',{name:'Insert selected date',exact:true}).click();await expect(source).toHaveValue('Before 2030-12-25 after');
 await source.evaluate((el:HTMLTextAreaElement)=>{el.focus();el.select();});
 await page.evaluate(()=>{for(const callback of (window as any).__caretFrames.splice(0))callback(performance.now());});
 await page.keyboard.type('Replacement text');await expect(source).toHaveValue('Replacement text');
});

test('combined temporal gallery inserts formatted manual plain text',async({page})=>{
 await login(page);await create(page,'Writing/Temporal formats.md','Before replace after');const source=page.getByLabel('Markdown source');
 for(const [format,value,expected,kind] of [['MM/DD/YYYY','2030-12-25','12/25/2030','date'],['DD/MM/YYYY','2030-12-25','25/12/2030','date'],['MMM D, YYYY','2030-12-25','Dec 25, 2030','date'],['D MMMM YYYY','2030-12-25','25 December 2030','date'],['HH:mm:ss','21:45:12','21:45:12','time'],['h:mm A','21:45','9:45 PM','time'],['h:mm:ss A','00:05:12','12:05:12 AM','time']]){
 await source.fill('Before replace after');await source.evaluate((el:HTMLTextAreaElement)=>el.setSelectionRange(7,14));await page.getByRole('button',{name:'Date & time',exact:true}).click();await expect(source).toHaveValue('Before replace after');await page.getByRole('button',{name:format,exact:true}).click();const dialog=page.getByRole('dialog',{name:`Insert ${kind}`,exact:true});await expect(dialog.getByRole('button',{name:'Current',exact:true})).toBeVisible();await dialog.getByRole('button',{name:'Manual',exact:true}).click();await dialog.getByLabel(kind==='date'?'Date':'Time',{exact:true}).fill(value);await dialog.getByRole('button',{name:`Insert selected ${kind}`,exact:true}).click();await expect(source).toHaveValue(`Before ${expected} after`);
 }
 await page.getByRole('button',{name:'Date & time',exact:true}).click();await page.getByRole('region',{name:'Date and time formats'}).getByRole('button',{name:'Cancel',exact:true}).click();await expect(source).toHaveValue('Before 12:05:12 AM after');
});

test('Code language chooser inserts tagged blocks and persists on desktop and touch',async({page,browser})=>{
 for(const touch of [false,true]){
 const context=await browser.newContext({hasTouch:touch,viewport:touch?{width:390,height:844}:{width:1280,height:900}});const p=await context.newPage();
 await login(p);await create(p,'Writing/Language '+(touch?'touch':'desktop')+'.md','Before replace after');const source=p.getByLabel('Markdown source');
 for(const language of ['bash','python','typescript','__custom__']){
 await source.fill('Before replace after');await source.evaluate((el:HTMLTextAreaElement)=>el.setSelectionRange(7,14));await p.getByRole('button',{name:'Blocks',exact:true}).click();await p.getByRole('button',{name:'Code block',exact:true}).click();
 const dialog=p.getByRole('dialog',{name:'Insert code block',exact:true});await expect(dialog.getByLabel('Block text')).not.toBeFocused();await selectDropdown(dialog.getByLabel('Code language'),language);if(language==='__custom__')await dialog.getByLabel('Language tag').fill('custom-lang');
 await dialog.getByLabel('Block text').fill('print(1)');await dialog.getByRole('button',{name:'Insert',exact:true}).click();await expect(source).toHaveValue('Before \n\n```'+(language==='__custom__'?'custom-lang':language)+'\nprint(1)\n```\n\n after');
 }
 await p.getByRole('button',{name:'Save file',exact:true}).click();await expect(p.locator('.network')).toHaveText('Synchronized');await p.reload();await expect(p.getByRole('button',{name:'Settings',exact:true})).toBeVisible();await openNote(p,'Language '+(touch?'touch':'desktop'));await expect(source).toContainText('```custom-lang');await context.close();
 }
});
